import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.HashMap;import java.util.Map;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int t = Integer.parseInt(br.readLine().trim());while (t-- > 0) {StringTokenizer st = new StringTokenizer(br.readLine());long a = Long.parseLong(st.nextToken());long b = Long.parseLong(st.nextToken());long c = Long.parseLong(st.nextToken());long d = Long.parseLong(st.nextToken());long m = Long.parseLong(st.nextToken());int n = Integer.parseInt(br.readLine().trim());long[] arr = new long[n];st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {arr[i] = Long.parseLong(st.nextToken());}Map<Long, Long> freq = new HashMap<>();for (int i = 0; i < n; i++) {long val = mod(arr[i] * arr[i], m);freq.put(val, freq.getOrDefault(val, 0L) + 1);}long count = 0;for (int i = 0; i < n; i++) {long x = arr[i];long term1 = mod(mod(a % m * mod(x % m * x % m, m), m) * (x % m), m);long term2 = mod(b % m * mod(x % m * x % m, m), m);long term3 = mod(c % m * (x % m), m);long target = mod(mod(mod(term1 + term2, m) + term3, m) + d % m, m);if (freq.containsKey(target)) {count = (count + freq.get(target)) % 1000000007;}}System.out.println(count);}}private static long mod(long n, long m) {long res = n % m;if (res < 0) res += m;return res;}}